package com.citacloud.springboot.contacloud.app.services;
import com.citacloud.springboot.contacloud.app.dto.*;import com.citacloud.springboot.contacloud.app.models.*;import com.citacloud.springboot.contacloud.app.repositories.*;import com.citacloud.springboot.contacloud.app.security.*;import org.springframework.data.domain.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.LocalDate;import java.util.*;
@Service public class ConteoFisicoService{
 private static final Set<Integer>SIZES=Set.of(10,25,50,100),LINE_SIZES=Set.of(5,10,20,25,50,100);private final ConteoFisicoRepository conteos;private final LineaConteoFisicoRepository lineas;private final IntentoConteoFisicoRepository intentos;private final AlcanceProductoConteoFisicoRepository alcance;private final AlmacenRepository almacenes;private final ProductRepository productos;private final ProductoCategoriaRepository categorias;private final InventoryMovementRepository movimientos;private final InventoryMovementService movimientoService;private final ConteoFisicoNumeroService numeros;private final AuditoriaService auditoria;
 public ConteoFisicoService(ConteoFisicoRepository c,LineaConteoFisicoRepository l,IntentoConteoFisicoRepository i,AlcanceProductoConteoFisicoRepository s,AlmacenRepository a,ProductRepository p,ProductoCategoriaRepository pc,InventoryMovementRepository m,InventoryMovementService ms,ConteoFisicoNumeroService n,AuditoriaService au){conteos=c;lineas=l;intentos=i;alcance=s;almacenes=a;productos=p;categorias=pc;movimientos=m;movimientoService=ms;numeros=n;auditoria=au;}
 @Transactional(readOnly=true)@PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('conteo_fisico.ver')")public Page<ConteoFisicoDto> buscar(String q,LocalDate desde,LocalDate hasta,EstadoConteoFisico estado,UUID almacen,TipoConteoFisico tipo,int page,int size){if(page<0||!SIZES.contains(size))throw new ReglaNegocioException("Paginación inválida.");if(desde!=null&&hasta!=null&&desde.isAfter(hasta))throw new ReglaNegocioException("La fecha inicial no puede ser posterior a la fecha final.");var p=TenantContext.principalActual();var result=conteos.buscar(p.tenantId(),p.empresaId(),text(q).toLowerCase(Locale.ROOT),desde,hasta,estado,almacen,tipo,PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"fecha").and(Sort.by(Sort.Direction.DESC,"creadoEn"))));Map<UUID,long[]> summary=new HashMap<>();if(!result.isEmpty())for(Object[] row:lineas.resumen(result.getContent().stream().map(ConteoFisico::getId).toList()))summary.put((UUID)row[0],new long[]{((Number)row[1]).longValue(),row[2]==null?0:((Number)row[2]).longValue()});return result.map(c->{long[] s=summary.getOrDefault(c.getId(),new long[2]);return map(c,List.of(),s[0],s[1],List.of());});}
 @Transactional(readOnly=true)@PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('conteo_fisico.ver')")public ConteoFisicoDto obtener(UUID id){return completo(seguro(id,false));}
 @Transactional(readOnly=true)@PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('conteo_fisico.ver')")public ConteoFisicoDto obtenerCabecera(UUID id){ConteoFisico c=seguro(id,false);long total=lineas.countByConteoId(id),contados=lineas.countByConteoIdAndCantidadContadaIsNotNull(id);long diferencias=0;var resumen=lineas.resumen(List.of(id));if(!resumen.isEmpty()&&resumen.get(0)[2]!=null)diferencias=((Number)resumen.get(0)[2]).longValue();return map(c,List.of(),total,diferencias,alcance.findAllByConteoId(id).stream().map(AlcanceProductoConteoFisico::getProductoId).toList());}
 @Transactional(readOnly=true)@PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('conteo_fisico.ver')")public ConteoFisicoCatalogosDto catalogos(){var p=TenantContext.principalActual();var ws=almacenes.findAllByTenantIdAndEmpresaIdAndActivoTrueOrderByNombre(p.tenantId(),p.empresaId()).stream().filter(w->EmpresaContext.permiteSucursal(w.getSucursalId())).map(w->new ConteoFisicoCatalogosDto.Almacen(w.getId(),w.getNombre(),w.getSucursal().getNombre())).toList();var cs=categorias.findAllByTenantIdAndEmpresaIdAndActivoTrueOrderByNombre(p.tenantId(),p.empresaId()).stream().map(c->new ConteoFisicoCatalogosDto.Categoria(c.getId(),c.getNombre())).toList();var ps=productos.findAllByTenantIdAndEmpresaIdAndActivoTrueAndControlaExistenciaTrueOrderByNombre(p.tenantId(),p.empresaId()).stream().filter(x->x.getTipo()==TipoProducto.PRODUCT).map(x->new ConteoFisicoCatalogosDto.Producto(x.getId(),x.getCodigo(),x.getNombre(),x.getUnidadMedida()==null?"Unidad":x.getUnidadMedida().getNombre())).toList();return new ConteoFisicoCatalogosDto(ws,cs,ps);}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('conteo_fisico.crear')")public ConteoFisicoDto crear(ConteoFisicoInput in){Validado v=validar(in);var p=TenantContext.principalActual();ConteoFisico c=conteos.saveAndFlush(new ConteoFisico(p.tenantId(),p.empresaId(),numeros.siguiente(p.tenantId(),p.empresaId()),v.fecha,v.almacen,v.categoria,v.tipo,v.modo,v.referencia,v.observacion,p.usuarioId()));guardarAlcance(c,v.productos);auditoria.registrar("PHYSICAL_COUNT_CREATED","INVENTORY_PHYSICAL_COUNT",c.getId(),detalle(c));return completo(c);}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('conteo_fisico.editar')")public ConteoFisicoDto actualizar(UUID id,ConteoFisicoInput in){ConteoFisico c=seguro(id,true);if(c.getEstado()!=EstadoConteoFisico.DRAFT)throw new ReglaNegocioException("Solo se puede editar un conteo en borrador.");if(in.version()!=null&&in.version()!=c.getVersion())throw new ReglaNegocioException("El conteo fue modificado por otro usuario. Actualiza la pantalla.");Validado v=validar(in);c.actualizar(v.fecha,v.almacen,v.categoria,v.tipo,v.modo,v.referencia,v.observacion,TenantContext.principalActual().usuarioId());alcance.deleteAllByConteoId(id);alcance.flush();guardarAlcance(c,v.productos);auditoria.registrar("PHYSICAL_COUNT_UPDATED","INVENTORY_PHYSICAL_COUNT",id,detalle(c));return completo(c);}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('conteo_fisico.iniciar')")public ConteoFisicoDto iniciar(UUID id){ConteoFisico c=seguro(id,true);if(c.getEstado()==EstadoConteoFisico.IN_PROGRESS)return completo(c);if(c.getEstado()!=EstadoConteoFisico.DRAFT)throw new ReglaNegocioException("Solo se puede iniciar un conteo en borrador.");var seleccion=productosAlcance(c);if(seleccion.isEmpty())throw new ReglaNegocioException("El alcance no contiene productos activos que controlen existencia.");int orden=1;for(Producto p:seleccion)lineas.save(new LineaConteoFisico(c,p,movimientos.saldo(c.getTenantId(),c.getEmpresaId(),c.getAlmacenId(),p.getId()),orden++));c.iniciar(TenantContext.principalActual().usuarioId());auditoria.registrar("PHYSICAL_COUNT_STARTED","INVENTORY_PHYSICAL_COUNT",id,detalle(c));return completo(c);}
 @Transactional(readOnly=true)@PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and (hasAuthority('conteo_fisico.ver') or hasAuthority('conteo_fisico.contar'))")public PaginaLineasConteoFisicoDto buscarLineas(UUID id,String q,int page,int size){if(page<0||!LINE_SIZES.contains(size))throw new ReglaNegocioException("Paginación inválida.");ConteoFisico c=seguro(id,false);Page<LineaConteoFisico> result=lineas.buscar(id,text(q).toLowerCase(Locale.ROOT),PageRequest.of(page,size,Sort.by("orden")));boolean ocultar=c.getModo()==ModoConteoFisico.BLIND&&c.getEstado()==EstadoConteoFisico.IN_PROGRESS;List<ConteoFisicoDto.Linea> items=result.getContent().stream().map(l->lineaDto(l,ocultar)).toList();long contados=lineas.countByConteoIdAndCantidadContadaIsNotNull(id),totalAlcance=lineas.countByConteoId(id);return new PaginaLineasConteoFisicoDto(items,result.getTotalElements(),contados,Math.max(0,totalAlcance-contados),result.getNumber(),result.getSize(),result.getTotalPages());}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and (hasAuthority('conteo_fisico.contar') or hasAuthority('conteo_fisico.recuento'))")public void guardarCaptura(UUID id,Map<UUID,BigDecimal> cantidades){ConteoFisico c=seguro(id,true);if(c.getEstado()!=EstadoConteoFisico.IN_PROGRESS)throw new ReglaNegocioException("El conteo no está en captura.");if(cantidades==null||cantidades.isEmpty())return;var u=TenantContext.principalActual().usuarioId();List<LineaConteoFisico> seleccion=lineas.bloquearLineas(id,cantidades.keySet());if(seleccion.size()!=cantidades.size())throw new ReglaNegocioException("Una o más líneas no pertenecen al conteo actual.");for(LineaConteoFisico l:seleccion){BigDecimal q=cantidades.get(l.getId());if(q!=null&&q.signum()<0)throw new ReglaNegocioException("La cantidad física no puede ser negativa.");if(q!=null&&!Objects.equals(q,l.getCantidadContada())){int n=Math.toIntExact(intentos.countByLineaId(l.getId())+1);intentos.save(new IntentoConteoFisico(l.getId(),n,q,u));}l.contar(q,u);}auditoria.registrar("PHYSICAL_COUNT_PROGRESS_SAVED","INVENTORY_PHYSICAL_COUNT",id,"{}");}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('conteo_fisico.finalizar')")public ConteoFisicoDto finalizar(UUID id){ConteoFisico c=seguro(id,true);if(c.getEstado()==EstadoConteoFisico.PENDING_CONFIRMATION)return completo(c);if(c.getEstado()!=EstadoConteoFisico.IN_PROGRESS)throw new ReglaNegocioException("El conteo no está en captura.");var ls=lineas.bloquearPorConteo(id);if(ls.stream().anyMatch(x->x.getCantidadContada()==null))throw new ReglaNegocioException("No se puede finalizar: todavía hay productos pendientes de conteo.");for(var l:ls)l.cerrar(movimientos.saldo(c.getTenantId(),c.getEmpresaId(),c.getAlmacenId(),l.getProductoId()));c.finalizar(TenantContext.principalActual().usuarioId());auditoria.registrar("PHYSICAL_COUNT_FINISHED","INVENTORY_PHYSICAL_COUNT",id,detalle(c));return completo(c);}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('conteo_fisico.confirmar')")public ConteoFisicoDto confirmar(UUID id){ConteoFisico c=seguro(id,true);if(c.getEstado()==EstadoConteoFisico.CONFIRMED)return completo(c);if(c.getEstado()!=EstadoConteoFisico.PENDING_CONFIRMATION)throw new ReglaNegocioException("El conteo no está pendiente de confirmación.");var principal=TenantContext.principalActual();for(LineaConteoFisico l:lineas.bloquearPorConteo(id)){productos.bloquear(l.getProductoId(),c.getTenantId(),c.getEmpresaId()).orElseThrow(()->new ReglaNegocioException("Uno de los productos ya no está disponible."));BigDecimal saldo=movimientos.saldo(c.getTenantId(),c.getEmpresaId(),c.getAlmacenId(),l.getProductoId());l.cerrar(saldo);if(l.getDiferencia().signum()!=0)movimientoService.conteo(c,l,l.getDiferencia().signum()>0?"IN":"OUT",principal.usuarioId());}c.confirmar(principal.usuarioId(),principal.nombre());auditoria.registrar("PHYSICAL_COUNT_CONFIRMED","INVENTORY_PHYSICAL_COUNT",id,detalle(c));return completo(c);}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('conteo_fisico.anular')")public ConteoFisicoDto anular(UUID id,String motivo){if(text(motivo).isBlank())throw new ReglaNegocioException("El motivo de anulación es obligatorio.");ConteoFisico c=seguro(id,true);if(c.getEstado()==EstadoConteoFisico.CANCELLED)return completo(c);c.anular(motivo.trim(),TenantContext.principalActual().usuarioId());auditoria.registrar("PHYSICAL_COUNT_CANCELLED","INVENTORY_PHYSICAL_COUNT",id,detalle(c));return completo(c);}
 private Validado validar(ConteoFisicoInput i){if(i==null||i.fecha()==null||i.almacenId()==null||i.tipo()==null||i.modo()==null)throw new ReglaNegocioException("Completa fecha, almacén, tipo y modo del conteo.");var p=TenantContext.principalActual();Almacen a=almacenes.findByIdAndTenantIdAndEmpresaId(i.almacenId(),p.tenantId(),p.empresaId()).filter(Almacen::isActivo).orElseThrow(()->new ReglaNegocioException("El almacén no está disponible."));UUID categoria=i.tipo()==TipoConteoFisico.PARTIAL?i.categoriaId():null;List<UUID> ps=i.tipo()==TipoConteoFisico.PARTIAL&&i.productos()!=null?i.productos().stream().distinct().toList():List.of();if(i.tipo()==TipoConteoFisico.PARTIAL&&categoria==null&&ps.isEmpty())throw new ReglaNegocioException("Selecciona una categoría o al menos un producto para el conteo parcial.");return new Validado(i.fecha(),a,categoria,i.tipo(),i.modo(),text(i.referencia()),text(i.observacion()),ps);}
 private List<Producto> productosAlcance(ConteoFisico c){var p=TenantContext.principalActual();var all=productos.findAllByTenantIdAndEmpresaIdAndActivoTrueAndControlaExistenciaTrueOrderByNombre(p.tenantId(),p.empresaId()).stream().filter(x->x.getTipo()==TipoProducto.PRODUCT).toList();if(c.getTipo()==TipoConteoFisico.COMPLETE)return all;Set<UUID> ids=new HashSet<>();alcance.findAllByConteoId(c.getId()).forEach(x->ids.add(x.getProductoId()));return all.stream().filter(x->(c.getCategoriaId()!=null&&c.getCategoriaId().equals(x.getCategoriaId()))||ids.contains(x.getId())).toList();}
 private void guardarAlcance(ConteoFisico c,List<UUID> ids){for(UUID id:ids){Producto p=productos.findByIdAndTenantIdAndEmpresaId(id,c.getTenantId(),c.getEmpresaId()).filter(x->x.isActivo()&&x.isControlaExistencia()&&x.getTipo()==TipoProducto.PRODUCT).orElseThrow(()->new ReglaNegocioException("Uno de los productos seleccionados no está disponible."));alcance.save(new AlcanceProductoConteoFisico(c,p.getId()));}}
 private ConteoFisico seguro(UUID id,boolean lock){var p=TenantContext.principalActual();return(lock?conteos.bloquear(id,p.tenantId(),p.empresaId()):conteos.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),p.empresaId())).orElseThrow(()->new RecursoNoEncontradoException("Conteo físico no encontrado."));}
 private ConteoFisicoDto completo(ConteoFisico c){List<LineaConteoFisico> ls=lineas.findAllByConteoIdOrderByOrden(c.getId());long diferencias=ls.stream().filter(x->x.getDiferencia()!=null&&x.getDiferencia().signum()!=0).count();List<UUID> scope=alcance.findAllByConteoId(c.getId()).stream().map(AlcanceProductoConteoFisico::getProductoId).toList();return map(c,ls,ls.size(),diferencias,scope);}private ConteoFisicoDto map(ConteoFisico c,List<LineaConteoFisico> ls,long productosCount,long diferenciasCount,List<UUID> scope){boolean ocultar=c.getModo()==ModoConteoFisico.BLIND&&c.getEstado()==EstadoConteoFisico.IN_PROGRESS;return new ConteoFisicoDto(c.getId(),c.getNumero(),c.getFecha(),c.getAlmacenId(),c.getAlmacenHistorico()!=null?c.getAlmacenHistorico():c.getAlmacen().getNombre(),c.getSucursalHistorica()!=null?c.getSucursalHistorica():c.getAlmacen().getSucursal().getNombre(),c.getCategoriaId(),c.getTipo(),c.getModo(),c.getReferencia(),c.getObservacion(),c.getEstado(),c.getVersion(),c.getIniciadoEn(),c.getFinalizadoEn(),c.getConfirmadoEn(),c.getConfirmadoPorNombre(),c.getAnuladoEn(),c.getMotivoAnulacion(),productosCount,diferenciasCount,scope,ls.stream().map(l->new ConteoFisicoDto.Linea(l.getId(),l.getProductoId(),l.getCodigo(),l.getProducto(),l.getUnidad(),ocultar?null:l.getCantidadInicial(),l.getCantidadContada(),ocultar?null:l.getCantidadTeorica(),ocultar?null:l.getDiferencia(),l.getVersion())).toList());}
 private static String text(String x){return x==null?"":x.trim();}private static String detalle(ConteoFisico c){return "{\"numero\":\""+c.getNumero()+"\",\"estado\":\""+c.getEstado()+"\"}";}private record Validado(LocalDate fecha,Almacen almacen,UUID categoria,TipoConteoFisico tipo,ModoConteoFisico modo,String referencia,String observacion,List<UUID> productos){}
 private static ConteoFisicoDto.Linea lineaDto(LineaConteoFisico l,boolean ocultar){return new ConteoFisicoDto.Linea(l.getId(),l.getProductoId(),l.getCodigo(),l.getProducto(),l.getUnidad(),ocultar?null:l.getCantidadInicial(),l.getCantidadContada(),ocultar?null:l.getCantidadTeorica(),ocultar?null:l.getDiferencia(),l.getVersion());}
}
